CREATE FUNCTION pharmacy_hospital_receiving_scope(t uuid,o uuid,write_access boolean)RETURNS boolean LANGUAGE sql STABLE AS $$
 SELECT COALESCE(hms_tenant_visible(t)AND t=NULLIF(current_setting('app.tenant_id',true),'')::uuid AND o=NULLIF(current_setting('app.pharmacy_receiving_outlet',true),'')::uuid AND current_setting('app.pharmacy_receiving_access',true)='authorized'AND current_setting('app.pharmacy_subject',true)=current_setting('app.actor_subject',true)AND NULLIF(current_setting('app.pharmacy_receiving_staff',true),'')::uuid<>'00000000-0000-0000-0000-000000000000'
 AND(NOT write_access OR current_setting('app.pharmacy_receiving_purpose',true)IN('record','review'))
 AND EXISTS(SELECT 1 FROM pharmacy_outlets x WHERE x.tenant_id=t AND x.id=o AND x.pharmacy_id=NULLIF(current_setting('app.pharmacy_receiving_pharmacy',true),'')::uuid),false)
$$;
CREATE TABLE pharmacy_supplier_receiving_heads(
 tenant_id uuid NOT NULL,shipment_id uuid NOT NULL,order_id uuid NOT NULL,hospital_id uuid NOT NULL,department_id uuid NOT NULL,pharmacy_id uuid NOT NULL,outlet_id uuid NOT NULL,version bigint NOT NULL CHECK(version BETWEEN 1 AND 9007199254740991),counted_units bigint NOT NULL CHECK(counted_units BETWEEN 0 AND 1000000000),accepted_units bigint NOT NULL CHECK(accepted_units BETWEEN 0 AND counted_units),rejected_units bigint NOT NULL CHECK(rejected_units BETWEEN 0 AND counted_units),closed boolean NOT NULL DEFAULT false,shipment jsonb NOT NULL,summary jsonb NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,
 PRIMARY KEY(tenant_id,shipment_id),CHECK(accepted_units+rejected_units=counted_units),CHECK(summary->>'shipment_id'IS NOT DISTINCT FROM shipment_id::text AND summary->>'owner_tenant_id'IS NOT DISTINCT FROM tenant_id::text AND summary->>'order_id'IS NOT DISTINCT FROM order_id::text AND summary->>'version'IS NOT DISTINCT FROM version::text AND summary->>'counted_units'IS NOT DISTINCT FROM counted_units::text AND summary->>'accepted_units'IS NOT DISTINCT FROM accepted_units::text AND summary->>'rejected_units'IS NOT DISTINCT FROM rejected_units::text AND(summary->>'closed')::boolean=closed)
);
ALTER TABLE pharmacy_supplier_receiving_heads ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_receiving_heads FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_receiving_heads USING(hms_tenant_visible(tenant_id)AND(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false)AND hospital_id=NULLIF(current_setting('app.pharmacy_receiving_hospital',true),'')::uuid AND department_id=NULLIF(current_setting('app.pharmacy_receiving_department',true),'')::uuid))WITH CHECK(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND hospital_id=NULLIF(current_setting('app.pharmacy_receiving_hospital',true),'')::uuid AND department_id=NULLIF(current_setting('app.pharmacy_receiving_department',true),'')::uuid);
CREATE TABLE pharmacy_supplier_receipts(
 tenant_id uuid NOT NULL,id uuid NOT NULL,shipment_id uuid NOT NULL,pharmacy_id uuid NOT NULL,outlet_id uuid NOT NULL,destination_batch_id uuid,quarantine_location_id uuid,counted_units bigint NOT NULL,accepted_units bigint NOT NULL,rejected_units bigint NOT NULL,intent_hash text NOT NULL CHECK(intent_hash~'^[a-f0-9]{64}$'),body jsonb NOT NULL,actor_subject text NOT NULL,actor_staff_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,outlet_id,id),FOREIGN KEY(tenant_id,shipment_id)REFERENCES pharmacy_supplier_receiving_heads(tenant_id,shipment_id)ON DELETE RESTRICT,
 CHECK(counted_units BETWEEN 1 AND 1000000000 AND accepted_units BETWEEN 0 AND counted_units AND rejected_units BETWEEN 0 AND counted_units AND accepted_units+rejected_units=counted_units),
 CHECK(body->>'id'IS NOT DISTINCT FROM id::text AND body->>'owner_tenant_id'IS NOT DISTINCT FROM tenant_id::text AND body->>'shipment_id'IS NOT DISTINCT FROM shipment_id::text AND body->>'pharmacy_id'IS NOT DISTINCT FROM pharmacy_id::text AND body->>'outlet_id'IS NOT DISTINCT FROM outlet_id::text AND body->>'actor_subject'IS NOT DISTINCT FROM actor_subject AND body->>'actor_staff_id'IS NOT DISTINCT FROM actor_staff_id::text AND body#>>'{input,counted_units}'IS NOT DISTINCT FROM counted_units::text AND body#>>'{input,accepted_units}'IS NOT DISTINCT FROM accepted_units::text AND body#>>'{input,rejected_units}'IS NOT DISTINCT FROM rejected_units::text),
 CHECK((accepted_units=0 AND destination_batch_id IS NULL AND quarantine_location_id IS NULL AND body->>'movement_id'IS NULL)OR(accepted_units>0 AND destination_batch_id IS NOT NULL AND quarantine_location_id IS NOT NULL AND body->>'movement_id'=id::text AND body#>>'{input,destination_batch_id}'=destination_batch_id::text AND body#>>'{input,quarantine_location_id}'=quarantine_location_id::text))
);
ALTER TABLE pharmacy_supplier_receipts ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_receipts FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_receipts USING(hms_tenant_visible(tenant_id)AND(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false)))WITH CHECK(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND actor_subject=current_setting('app.actor_subject',true)AND actor_staff_id=NULLIF(current_setting('app.pharmacy_receiving_staff',true),'')::uuid);
CREATE INDEX ON pharmacy_supplier_receipts(tenant_id,shipment_id,created_at DESC,id DESC);
CREATE TABLE pharmacy_supplier_receiving_closures(
 tenant_id uuid NOT NULL,id uuid NOT NULL,shipment_id uuid NOT NULL,outlet_id uuid NOT NULL,input jsonb NOT NULL,body jsonb NOT NULL,actor_subject text NOT NULL,actor_staff_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,shipment_id),FOREIGN KEY(tenant_id,shipment_id)REFERENCES pharmacy_supplier_receiving_heads(tenant_id,shipment_id)ON DELETE RESTRICT,
 CHECK(body->>'id'IS NOT DISTINCT FROM id::text AND body->>'owner_tenant_id'IS NOT DISTINCT FROM tenant_id::text AND body->>'shipment_id'IS NOT DISTINCT FROM shipment_id::text AND body->>'actor_subject'IS NOT DISTINCT FROM actor_subject AND body->>'actor_staff_id'IS NOT DISTINCT FROM actor_staff_id::text)
);
ALTER TABLE pharmacy_supplier_receiving_closures ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_receiving_closures FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_receiving_closures USING(hms_tenant_visible(tenant_id)AND(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false)))WITH CHECK(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND actor_subject=current_setting('app.actor_subject',true)AND actor_staff_id=NULLIF(current_setting('app.pharmacy_receiving_staff',true),'')::uuid);
DO $$DECLARE tab text;prior text;BEGIN
 FOREACH tab IN ARRAY ARRAY['pharmacy_stock_locations','pharmacy_stock_batches','pharmacy_stock_movements','pharmacy_catalogue_products']LOOP
 SELECT pg_get_expr(polqual,polrelid)INTO STRICT prior FROM pg_policy WHERE polrelid=tab::regclass AND polname='tenant_isolation';EXECUTE format('ALTER POLICY tenant_isolation ON %I USING((%s)OR pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false))',tab,prior);END LOOP;
 SELECT pg_get_expr(polwithcheck,polrelid)INTO STRICT prior FROM pg_policy WHERE polrelid='pharmacy_stock_batches'::regclass AND polname='tenant_isolation';EXECUTE format('ALTER POLICY tenant_isolation ON pharmacy_stock_batches WITH CHECK((%s)OR pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true))',prior);
 SELECT pg_get_expr(polwithcheck,polrelid)INTO STRICT prior FROM pg_policy WHERE polrelid='pharmacy_stock_movements'::regclass AND polname='tenant_isolation';EXECUTE format('ALTER POLICY tenant_isolation ON pharmacy_stock_movements WITH CHECK((%s)OR(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND kind=''receipt''AND actor_subject=current_setting(''app.actor_subject'',true)AND EXISTS(SELECT 1 FROM pharmacy_supplier_receipts r WHERE r.tenant_id=pharmacy_stock_movements.tenant_id AND r.outlet_id=pharmacy_stock_movements.outlet_id AND r.id=pharmacy_stock_movements.id AND r.destination_batch_id=pharmacy_stock_movements.batch_id AND r.quarantine_location_id=pharmacy_stock_movements.location_id AND r.accepted_units=pharmacy_stock_movements.quantity_units)))',prior);
END $$;
CREATE TRIGGER pharmacy_supplier_receipt_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON pharmacy_supplier_receipts FOR EACH STATEMENT EXECUTE FUNCTION pharmacy_supplier_evidence_immutable();
CREATE TRIGGER pharmacy_supplier_closure_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON pharmacy_supplier_receiving_closures FOR EACH STATEMENT EXECUTE FUNCTION pharmacy_supplier_evidence_immutable();
CREATE TRIGGER pharmacy_supplier_receipt_audit AFTER INSERT ON pharmacy_supplier_receipts FOR EACH ROW EXECUTE FUNCTION audit_record_change();
CREATE TRIGGER pharmacy_supplier_closure_audit AFTER INSERT ON pharmacy_supplier_receiving_closures FOR EACH ROW EXECUTE FUNCTION audit_record_change();
CREATE TRIGGER pharmacy_supplier_receiving_head_audit AFTER INSERT OR UPDATE ON pharmacy_supplier_receiving_heads FOR EACH ROW EXECUTE FUNCTION audit_record_change();
CREATE TABLE pharmacy_supplier_receiving_clearances(
 tenant_id uuid NOT NULL,id uuid NOT NULL,receipt_id uuid NOT NULL,shipment_id uuid NOT NULL,outlet_id uuid NOT NULL,summary_version bigint NOT NULL,reason text NOT NULL CHECK(length(reason)BETWEEN 1 AND 500),actor_subject text NOT NULL,actor_staff_id uuid NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,receipt_id,summary_version),FOREIGN KEY(tenant_id,receipt_id)REFERENCES pharmacy_supplier_receipts(tenant_id,id)ON DELETE RESTRICT
);
ALTER TABLE pharmacy_supplier_receiving_clearances ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_receiving_clearances FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_receiving_clearances USING(hms_tenant_visible(tenant_id)AND(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false)OR pharmacy_outlet_allowed(tenant_id,outlet_id,false)))WITH CHECK(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true)AND current_setting('app.pharmacy_receiving_purpose',true)='review'AND actor_subject=current_setting('app.actor_subject',true)AND actor_staff_id=NULLIF(current_setting('app.pharmacy_receiving_staff',true),'')::uuid AND EXISTS(SELECT 1 FROM pharmacy_supplier_receipts r WHERE r.tenant_id=pharmacy_supplier_receiving_clearances.tenant_id AND r.id=receipt_id AND r.actor_staff_id<>pharmacy_supplier_receiving_clearances.actor_staff_id));
CREATE TRIGGER pharmacy_supplier_clearance_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON pharmacy_supplier_receiving_clearances FOR EACH STATEMENT EXECUTE FUNCTION pharmacy_supplier_evidence_immutable();
CREATE TRIGGER pharmacy_supplier_clearance_audit AFTER INSERT ON pharmacy_supplier_receiving_clearances FOR EACH ROW EXECUTE FUNCTION audit_record_change();

CREATE TABLE pharmacy_supplier_batch_sources(
 tenant_id uuid NOT NULL,outlet_id uuid NOT NULL,batch_id uuid NOT NULL,receipt_id uuid NOT NULL,shipment_id uuid NOT NULL,source jsonb NOT NULL,current_summary_version bigint NOT NULL,clearance_version bigint NOT NULL DEFAULT 0,
 PRIMARY KEY(tenant_id,outlet_id,batch_id,receipt_id),FOREIGN KEY(tenant_id,receipt_id)REFERENCES pharmacy_supplier_receipts(tenant_id,id)ON DELETE RESTRICT
);
ALTER TABLE pharmacy_supplier_batch_sources ENABLE ROW LEVEL SECURITY;ALTER TABLE pharmacy_supplier_batch_sources FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON pharmacy_supplier_batch_sources USING(hms_tenant_visible(tenant_id)AND(pharmacy_outlet_allowed(tenant_id,outlet_id,false)OR pharmacy_operating_stock_scope(tenant_id,outlet_id,'read')OR pharmacy_hospital_receiving_scope(tenant_id,outlet_id,false)))WITH CHECK(pharmacy_hospital_receiving_scope(tenant_id,outlet_id,true));
CREATE INDEX ON pharmacy_supplier_batch_sources(tenant_id,shipment_id);
-- This minimal stock-owned provenance is visible to release checks without exposing private Staff receipts.
CREATE FUNCTION pharmacy_supplier_release_guard()RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r record;
BEGIN
 FOR r IN SELECT receipt_id,current_summary_version,clearance_version FROM pharmacy_supplier_batch_sources WHERE tenant_id=NEW.tenant_id AND outlet_id=NEW.outlet_id AND batch_id=NEW.batch_id LOOP
 IF r.clearance_version<>r.current_summary_version OR position('|'||r.receipt_id::text||'|'IN COALESCE(current_setting('app.pharmacy_supplier_safe_receipts',true),''))=0 THEN RAISE EXCEPTION 'supplier goods need independent review and current source safety' USING ERRCODE='23514';END IF;END LOOP;
 RETURN NEW;
END $$;
CREATE TRIGGER pharmacy_supplier_release_guard BEFORE INSERT ON pharmacy_stock_releases FOR EACH ROW EXECUTE FUNCTION pharmacy_supplier_release_guard();
